"""Evaluation helpers (R9, R10): metrics are computed only AFTER scores exist.

Every function takes (scores, labels) in that order so the labels can never be
consumed by the scoring pipeline.
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)

__all__ = ["auc_roc", "auc_pr", "auc_pr_trapz", "summarize"]


def auc_roc(scores, labels) -> float:
    return float(roc_auc_score(np.asarray(labels), np.asarray(scores)))


def auc_pr(scores, labels) -> float:
    """Primary AUC-PR: sklearn average_precision_score (ADBench convention)."""
    return float(average_precision_score(np.asarray(labels), np.asarray(scores)))


def auc_pr_trapz(scores, labels) -> float:
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    precision, recall, _ = precision_recall_curve(np.asarray(labels), np.asarray(scores))
    return float(-np.sum(np.diff(recall) * (precision[:-1] + precision[1:]) / 2.0))


def summarize(values):
    v = np.asarray(values, dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

